const num=n=>new Intl.NumberFormat(lang==='bn'?'bn-BD':'en-GB').format(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean=s=>s.replace(/^[^\p{L}]+/u,'');
const iconPaths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',settings:'<path d="M4 6h7m4 0h5M4 12h2m4 0h10M4 18h10m4 0h2"/><circle cx="13" cy="6" r="2"/><circle cx="8" cy="12" r="2"/><circle cx="16" cy="18" r="2"/>',leaf:'<path d="M5 17C1 7 12 2 21 3c2 12-6 20-15 14M4 21 17 7m-7 7-1-5m3 3 5 1"/>',sprout:'<path d="M12 22V11M12 16C3 17 2 9 3 6c8-1 11 4 9 10m0-5C11 4 16 1 22 2c1 7-3 11-10 9"/>',plant:'<path d="M6 15h12l-2 7H8l-2-7Zm6 0V6m0 6C5 13 3 8 4 5c6 0 8 3 8 7m0-4c-1-5 3-7 7-6 1 5-2 7-7 6"/>',grain:'<path d="M12 23V4m0 14c-5 0-7-3-7-6 5 0 7 3 7 6Zm0-7C7 11 5 8 6 5c4 1 6 3 6 6Zm0 4c5 0 7-3 7-6-5 0-7 3-7 6Zm0-7c4 0 6-3 5-6-3 0-5 3-5 6Z"/>',map:'<path d="m2 6 6-3 8 3 6-3v15l-6 3-8-3-6 3V6Zm6-3v15m8-12v15"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Z"/><path d="m8 12 3 3 5-6"/>',check:'<path d="m5 12 4 4L19 6"/>',help:'<path d="M21 11a9 9 0 0 1-9 9H5l-4 3 2-7a9 9 0 1 1 18-5Z"/><path d="M8 9a4 4 0 0 1 7 0c0 3-3 2-3 5m0 3h.01"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',moon:'<path d="M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11Z"/>',phone:'<path d="m5 3 4 1 1 5-3 2c1 3 3 5 6 6l2-3 5 1 1 4c-7 6-24-11-16-16Z"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="m2 6 10 8L22 6"/>',pin:'<path d="M20 9c0 6-8 13-8 13S4 15 4 9a8 8 0 0 1 16 0Z"/><circle cx="12" cy="9" r="2.5"/>',external:'<path d="M14 3h7v7m0-7L10 14m1-10H4v17h17v-7"/>',book:'<path d="M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1m0-16c4-3 8-2 10-1v16c-4-2-7-1-10 1V5Z"/>',bug:'<path d="M8 7h8v10a4 4 0 0 1-8 0V7Zm2 0V4h4v3M3 9l5 2m8 0 5-2M3 16h5m8 0h5M5 23l4-4m6 0 4 4M12 8v13"/>',bottle:'<path d="M9 2h6v4l3 4v12H6V10l3-4V2Zm-3 9h12M9 2v3h6M9 16h6m-3-3v6"/>',flask:'<path d="M8 2h8m-6 0v7L3 20c0 2 18 2 18 0L14 9V2M6 15h12"/>',fruit:'<path d="M12 8C6 2 0 9 3 17s7 6 9 5c2 1 6 3 9-5S18 2 12 8Zm0 0c0-5 3-7 7-6 0 4-3 6-7 6Z"/>',soil:'<path d="M2 20h20M4 16l3-5 4 3 3-7 6 9H4Zm8-9V2m0 3 4-2m-4 2L8 3"/>',drop:'<path d="M12 2S3 12 3 16a9 9 0 0 0 18 0c0-4-9-14-9-14Zm-5 14c0 3 2 4 4 4"/>',plus:'<path d="M5 12h14M12 5v14"/>',minus:'<path d="M5 12h14"/>',reset:'<path d="M3 10a9 9 0 1 1 2 9M3 3v7h7"/>',target:'<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2"/><path d="M12 1v4m0 14v4M1 12h4m14 0h4"/>',copy:'<rect x="8" y="8" width="13" height="14" rx="2"/><path d="M16 8V2H2v14h6"/>',download:'<path d="M12 2v14m-5-5 5 5 5-5M3 16v6h18v-6"/>',photo:'<rect x="2" y="4" width="20" height="16" rx="2"/><circle cx="8" cy="9" r="2"/><path d="m3 19 6-6 4 3 4-6 5 6"/>',lock:'<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};
const I=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[name]||iconPaths.leaf}</svg>`;
const navItems=[['home',bi('Home','হোম')],['crops',bi('Crops','ফসল')],['pests',bi('Pest & Disease','পোকা ও রোগ')],['ipm',bi('IPM','আইপিএম')],['products',bi('Products','পণ্য')],['aez',bi('Agro Zones','কৃষি অঞ্চল')],['help',bi('Farmer Help','কৃষক সহায়তা')]];
const route=()=>location.hash.slice(1).split('?')[0]||'home';
const link=(href,text,cls='link')=>`<a class="${cls}" href="#${href}">${text}${I('arrow')}</a>`;
const sourceLink=(i,label)=>`<a class="link" href="${lang==='bn'&&SOURCES[i].bnurl?SOURCES[i].bnurl:SOURCES[i].url}" target="_blank" rel="noopener noreferrer">${label||L(SOURCES[i].title)} ${I('external')}</a>`;
const titleOf=(data,id)=>clean(data[id][lang].title);
function header(){const current=route().split('/')[0],r=({crop:'crops',category:'products'})[current]||current;$('#header').innerHTML=`<div class="topbar"><a class="brand" href="#home" aria-label="Agri Solution BD"><img src="assets/leaf.svg" alt=""><span><strong>Agri Solution BD</strong><small>zee · agri</small></span></a><nav aria-label="${t('Main navigation','প্রধান নেভিগেশন')}" class="${menuOpen?'open':''}">${navItems.map(([id,n])=>`<a href="#${id}" ${r===id?'aria-current="page"':''}>${L(n)}</a>`).join('')}</nav><div class="actions"><button class="icon-button" data-action="search" aria-label="${t('Search agriculture','কৃষি তথ্য খুঁজুন')}">${I('search')}</button><button class="icon-button settings-button" data-action="settings" aria-label="${t('Settings','সেটিংস')}">${I('settings')}</button><button class="lang-button" data-action="language" lang="${lang==='en'?'bn':'en'}" aria-label="${t('Switch to Bangla','ইংরেজিতে দেখুন')}">${t('বাংলা','English')}</button><button class="icon-button menu-button" data-action="menu" aria-expanded="${menuOpen}" aria-label="${t('Open navigation','মেনু খুলুন')}">${I(menuOpen?'close':'menu')}</button></div></div>`;}
function footer(){$('#footer').innerHTML=`<div class="wrap"><div class="footer-grid"><div><a class="brand" href="#home"><img src="assets/leaf.svg" alt=""><span><strong>Agri Solution BD</strong><small>zee · agri</small></span></a><p style="font-size:11px;margin-top:14px">${t('Knowledge for better growing. Help for everyone.','ভালো চাষের জ্ঞান। সবার জন্য সহায়তা।')}</p></div><div class="footer-links"><a href="#about">${t('About Me','আমার সম্পর্কে')}</a><a href="#contact">${t('Contact','যোগাযোগ')}</a><a href="#sources">${t('Sources & information','তথ্যসূত্র')}</a><button class="link" style="background:none;border:0;padding:0;font-size:11px" data-action="settings">${t('Settings','সেটিংস')}</button></div></div><div class="footer-bottom"><span>© ${new Intl.NumberFormat(lang==='bn'?'bn-BD':'en-GB',{useGrouping:false}).format(new Date().getFullYear())} Agri Solution BD · ${t('Chattogram, Bangladesh','চট্টগ্রাম, বাংলাদেশ')}</span><span class="private-dot">${t('Your private agriculture workspace','আপনার ব্যক্তিগত কৃষি সাইট')}</span></div></div><a class="mobile-help" href="#help">${I('help')}${t('Get free farmer help','বিনামূল্যে কৃষি সহায়তা নিন')}${I('arrow')}</a>`;}
function pageTop(title,desc,section){return `<div class="page-top"><div class="breadcrumb"><a href="#home">${t('Home','হোম')}</a>${I('chevron')}${section?`<a href="#${section[0]}">${section[1]}</a>${I('chevron')}`:''}<span>${title}</span></div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`;}
function sectionHead(eyebrow,title,desc,href,label){return `<div class="section-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${href?link(href,label||t('Explore all','সব দেখুন')):''}</div>`;}
function cropArt(id,detail=false){const image=CROP_IMAGES[id];return `<div class="crop-art ${image?'has-photo':''} ${detail?'crop-detail-art':''}">${image?`<img src="${image}" alt="${esc(titleOf(cropData,id))}" loading="${detail?'eager':'lazy'}" decoding="async" width="960" height="640">`:I(['rice','wheat','maize'].includes(id)?'grain':'leaf')}<span class="tag">${L(CROP_EXTRA[id].season)}</span>${!image?`<span class="crop-photo-note">${t('Photo coming soon','ছবি শীঘ্রই যুক্ত হবে')}</span>`:''}</div>`;}
function cropCards(ids){return ids.map(id=>`<a class="card crop-card" href="#crop/${id}">${cropArt(id)}<div class="card-pad"><div class="mini-label">${t('Crop guide','ফসল নির্দেশিকা')}</div><h3>${titleOf(cropData,id)}</h3><p>${esc(cropData[id][lang].text)}</p><span class="link">${t('Growing guide','চাষের তথ্য')}${I('arrow')}</span></div></a>`).join('');}
function filterCrops(query=''){const q=query.trim().toLocaleLowerCase();const ids=Object.keys(cropData).filter(id=>[id,cropData[id].en.title,cropData[id].bn.title].join(' ').toLocaleLowerCase().includes(q));$('#crop-results').innerHTML=ids.length?`<div class="grid three">${cropCards(ids)}</div>`:`<div class="empty">${t('No crops found. Try another name.','ফসল পাওয়া যায়নি। অন্য নাম লিখুন।')}</div>`;$('#crop-count').textContent=t(`${ids.length} crops`,`${num(ids.length)}টি ফসল`);}

function productCards(ids){return ids.map(id=>`<a class="card category-card" href="#category/${id}">${I(PRODUCT_EXTRA[id].icon)}<div><h3>${titleOf(productData,id)}</h3><p>${t('Explore category','বিস্তারিত জানুন')} ↗</p></div></a>`).join('');}
function helpBanner(){return `<div class="card help-banner"><div><div class="eyebrow">${t('Here to help','সহায়তায় পাশে আছি')}</div><h2>${t('A growing problem? Let’s work on it.','চাষের সমস্যা? একসাথে সমাধান খুঁজি।')}</h2><p>${t('Tell us about your crop, location and what you’re seeing. Prepare a clear question and connect for practical help.','ফসল, এলাকা ও সমস্যার লক্ষণ জানান। প্রশ্ন সাজিয়ে বাস্তবসম্মত সহায়তার জন্য যোগাযোগ করুন।')}</p></div>${link('help',t('Get farmer help','কৃষি সহায়তা নিন'),'btn pale')}</div>`;}
function home(){return `<div class="wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow">${t('Rooted in Bangladesh','বাংলাদেশের কৃষির সাথে')}</div><h1>${t('Better growing<br>begins with the<br><em>right knowledge.</em>','সঠিক জ্ঞানেই<br>শুরু হোক<br><em>সমৃদ্ধ কৃষি।</em>')}</h1><p>${t('Your companion for crops, soil and everything that grows. Explore trusted agriculture information, useful inputs and free farmer support.','ফসল, মাটি ও সবুজের পথে আপনার সঙ্গী। জানুন নির্ভরযোগ্য কৃষি তথ্য, প্রয়োজনীয় উপকরণ ও বিনামূল্যের কৃষি সহায়তা।')}</p><div class="hero-buttons">${link('crops',t('Explore agriculture','কৃষি সম্পর্কে জানুন'),'btn')}${link('aez',t('Find your agro zone','কৃষি অঞ্চল দেখুন'),'btn secondary')}</div><div class="hero-proof"><span>${I('check')}${t('Bangladesh focused','বাংলাদেশের কৃষির জন্য')}</span><span>${I('check')}${t('বাংলা & English','বাংলা ও ইংরেজি')}</span><span>${I('check')}${t('Free guidance','বিনামূল্যে সহায়তা')}</span></div></div><div class="hero-image"><img src="assets/fields.jpg" alt="${t('Green cultivated countryside','সবুজ চাষের জমি')}" fetchpriority="high"><div class="image-badge"><strong>${num(30)}</strong><small>${t('AGRO-ECOLOGICAL<br>ZONES','কৃষি-পরিবেশ<br>অঞ্চল')}</small></div><div class="image-note"><div><small>${t('LEARN. GROW. SHARE.','জানুন। ফলান। ছড়িয়ে দিন।')}</small><strong>${t('A little knowledge.<br>A greener tomorrow.','একটু জ্ঞান।<br>আরও সবুজ আগামী।')}</strong></div><a class="round" href="#aez" aria-label="${t('Explore agro zones','কৃষি অঞ্চল দেখুন')}">${I('arrow')}</a></div></div></section><div class="pathways">${[['map','aez',t('Know your land','আপনার জমিকে জানুন'),t('Explore all 30 agro-ecological zones','৩০টি কৃষি-পরিবেশ অঞ্চল দেখুন')],['shield','pests',t('Keep crops healthy','ফসল রাখুন সুস্থ'),t('Recognise pests, diseases & symptoms','পোকা, রোগ ও লক্ষণ চিনুন')],['sprout','products',t('Find the right inputs','সঠিক উপকরণ বাছুন'),t('Seeds, plants, nutrients & more','বীজ, চারা, পুষ্টি ও আরও অনেক কিছু')]].map(([ic,url,ti,txt])=>`<a class="pathway" href="#${url}"><div class="badge">${I(ic)}</div><div><h3>${ti}</h3><p>${txt}</p></div>${I('arrow')}</a>`).join('')}</div><section class="section">${sectionHead(t('From seed to harvest','বীজ থেকে ফসল'),t('Grow with a little more confidence.','আস্থা নিয়ে এগিয়ে চলুক চাষ।'),t('Practical starting points for the crops you care for.','আপনার ফসলের জন্য প্রয়োজনীয় প্রাথমিক তথ্য।'),'crops',t('All crop guides','সব ফসলের তথ্য'))}<div class="grid three">${cropCards(['rice','maize','tomato'])}</div></section><section class="aez-banner"><div class="content"><div class="eyebrow">${t('A country of growing possibilities','কৃষির সম্ভাবনায় বাংলাদেশ')}</div><h2>${t('Different land.<br>Different possibilities.','মাটি ভিন্ন।<br>সম্ভাবনাও ভিন্ন।')}</h2><p>${t('Explore Bangladesh’s landscapes through an interactive AEZ map. Select a zone to discover its character and source-based information.','ইন্টার‌্যাক্টিভ এইজেড মানচিত্রে বাংলাদেশের ভূপ্রকৃতি দেখুন। অঞ্চল বেছে তার পরিচয় ও তথ্যসূত্র জানুন।')}</p>${link('aez',t('Explore the AEZ map','এইজেড মানচিত্র দেখুন'),'btn')}<div class="stat-row"><div><strong>${num(30)}</strong><small>${t('Zones','অঞ্চল')}</small></div><div><strong>${num(88)}</strong><small>${t('Subregions','উপ-অঞ্চল')}</small></div><div><strong>${num(535)}</strong><small>${t('Units','একক')}</small></div></div></div><div class="map-decoration" id="home-map" aria-hidden="true"></div></section><section class="section">${sectionHead(t('Useful inputs, informed choices','প্রয়োজনীয় উপকরণ, সচেতন নির্বাচন'),t('Good growing starts here.','ভালো চাষের শুরু এখানেই।'),t('Explore product categories and what to check before you choose.','পণ্যের ধরন জানুন এবং নির্বাচনের আগে কী যাচাই করবেন দেখুন।'),'products',t('All categories','সব ধরন'))}<div class="grid four">${productCards(['seeds','seedlings','biopesticides','organic'])}</div></section>${helpBanner()}</div>`;}
function cropsPage(){return `<div class="wrap">${pageTop(t('Crop information','ফসলের তথ্য'),t('Find a practical starting point, then adapt it to your season, land and local advice.','প্রাথমিক তথ্য জেনে আপনার মৌসুম, জমি ও স্থানীয় পরামর্শ অনুযায়ী কাজে লাগান।'))}<div class="page-content"><div class="toolbar"><label class="sr-only" for="crop-search">${t('Search crops','ফসল খুঁজুন')}</label><input type="search" id="crop-search" placeholder="${t('Search crops in English or Bangla','বাংলা বা ইংরেজিতে ফসল খুঁজুন')}"><span id="crop-count" role="status">${num(Object.keys(cropData).length)} ${t('crops','টি ফসল')}</span></div><div id="crop-results"><div class="grid three">${cropCards(Object.keys(cropData))}</div></div><div class="notice">${t('Planting windows and inputs vary by variety and location. Ask your local agriculture office for a field-specific plan.','জাত ও স্থানভেদে বপনের সময় ও উপকরণ বদলায়। জমিভিত্তিক পরিকল্পনার জন্য স্থানীয় কৃষি অফিসের পরামর্শ নিন।')}</div></div></div>`;}
function cropPage(id){if(!cropData[id])return notFound();let d=cropData[id][lang],ex=CROP_EXTRA[id];return `<div class="wrap">${pageTop(clean(d.title),d.text,['crops',t('Crops','ফসল')])}<div class="page-content detail-layout"><div class="stack">${CROP_IMAGES[id]?`<section class="card">${cropArt(id,true)}</section>`:''}<section class="card card-pad"><h2>${t('Growing essentials','চাষের প্রাথমিক বিষয়')}</h2><div class="facts"><div class="fact"><small>${t('Season','মৌসুম')}</small><strong>${L(ex.season)}</strong></div><div class="fact"><small>${t('Land & water','জমি ও পানি')}</small><strong>${L(ex.soil)}</strong></div><div class="fact"><small>${t('Crop care','পরিচর্যা')}</small><strong>${L(ex.care)}</strong></div></div></section><section class="card card-pad"><h2>${t('From planting to harvest','রোপণ থেকে সংগ্রহ')}</h2><ul class="list"><li>${t('Choose healthy planting material and a locally suitable variety.','সুস্থ রোপণ উপকরণ ও স্থানোপযোগী জাত নিন।')}</li><li>${t('Use a soil test and plan irrigation and drainage before planting.','চাষের আগে মাটি পরীক্ষা, সেচ ও নিষ্কাশন পরিকল্পনা করুন।')}</li><li>${t('Inspect regularly; record symptoms before taking action.','নিয়মিত দেখুন; ব্যবস্থা নেওয়ার আগে লক্ষণ লিখে রাখুন।')}</li><li>${t('Harvest at the correct maturity for the variety and intended use. Keep produce clean and dry as appropriate.','জাত ও ব্যবহারের উপযোগী পরিপক্বতায় সংগ্রহ করুন। প্রয়োজন অনুযায়ী ফসল পরিষ্কার ও শুকনো রাখুন।')}</li></ul></section></div><aside class="stack"><div class="card card-pad"><div class="eyebrow">${t('Make it local','স্থানীয়ভাবে কাজে লাগান')}</div><h3>${t('Start with your agro zone','শুরু করুন কৃষি অঞ্চল দিয়ে')}</h3><p>${t('Use the map to understand the wider landscape. A zone does not replace a field soil test.','বড় এলাকার ভূপ্রকৃতি বুঝতে মানচিত্র দেখুন। অঞ্চলভিত্তিক তথ্য মাটি পরীক্ষার বিকল্প নয়।')}</p>${link('aez',t('Explore zones','অঞ্চল দেখুন'))}</div><div class="card card-pad"><h3>${t('Need help with this crop?','এই ফসলে সহায়তা দরকার?')}</h3><p>${t('Share the crop stage, location and symptoms.','ফসলের পর্যায়, এলাকা ও লক্ষণ জানান।')}</p><button class="btn full" style="margin-top:20px" data-action="crop-help" data-id="${id}">${t('Prepare a question','প্রশ্ন প্রস্তুত করুন')}${I('arrow')}</button></div><div class="card card-pad">${link('pests',t('Pests & diseases','পোকা ও রোগ'))}${link('ipm',t('Learn about IPM','আইপিএম জানুন'))}</div></aside></div></div>`;}
// Preserve the original pest profiles; correct the lure guidance for species-specific use.
const fruitFly=pestData.find(p=>p.en.name==='Fruit Fly');if(fruitFly){fruitFly.en.control='Management: Collect infested and fallen fruit, bag fruit where practical, and use a lure matched to the identified species. Cue-lure and methyl eugenol attract different fruit-fly groups; ask a local adviser before choosing a trap.';fruitFly.bn.control='ব্যবস্থাপনা: আক্রান্ত ও ঝরা ফল সংগ্রহ করুন, সম্ভব হলে ফল ব্যাগিং করুন এবং শনাক্ত প্রজাতির উপযোগী লিউর নিন। কিউ-লিউর ও মিথাইল ইউজেনল ভিন্ন ফলের মাছিকে আকর্ষণ করে; ফাঁদ বাছার আগে স্থানীয় পরামর্শ নিন।';}
const diseases=[{en:{name:'Rice blast',sci:'Magnaporthe oryzae',crop:'Crop: Rice',damage:'Spindle-shaped leaf lesions with pale centres can be associated with blast; neck infection can leave panicles empty. Other causes can look similar.',control:'Use locally recommended resistant varieties and balanced nitrogen. Ask an extension adviser to confirm the cause before treatment.'},bn:{name:'ধানের ব্লাস্ট',sci:'Magnaporthe oryzae',crop:'ফসল: ধান',damage:'ফ্যাকাশে কেন্দ্রযুক্ত মাকু আকৃতির দাগ ব্লাস্টের লক্ষণ হতে পারে; শীষের গোড়ায় আক্রমণে চিটা হতে পারে। অন্য কারণেও এমন লক্ষণ হয়।',control:'স্থানীয় সুপারিশকৃত প্রতিরোধী জাত ও সুষম নাইট্রোজেন ব্যবহার করুন। ব্যবস্থাপনার আগে কৃষি পরামর্শককে দিয়ে কারণ নিশ্চিত করুন।'}},{en:{name:'Leaf curl symptoms',sci:'Multiple causes; diagnosis required',crop:'Crop: Tomato and chili',damage:'Curled leaves and stunted growth may be associated with viruses, mites, herbicide injury or other stress. Whiteflies can transmit some leaf-curl viruses.',control:'Use healthy seedlings, protect nurseries and monitor whiteflies. A pesticide cannot cure a virus-infected plant; seek diagnosis before removing plants or spraying.'},bn:{name:'পাতা কোঁকড়ানো লক্ষণ',sci:'একাধিক কারণ; রোগনির্ণয় দরকার',crop:'ফসল: টমেটো ও মরিচ',damage:'কোঁকড়ানো পাতা ও খর্ব বৃদ্ধি ভাইরাস, মাকড়, আগাছানাশকের ক্ষতি বা অন্য চাপ থেকে হতে পারে। সাদা মাছি কিছু পাতা কোঁকড়ানো ভাইরাস ছড়ায়।',control:'সুস্থ চারা, সুরক্ষিত নার্সারি ও সাদা মাছি পর্যবেক্ষণ জরুরি। বালাইনাশকে ভাইরাস আক্রান্ত গাছ সারে না; গাছ সরানো বা স্প্রের আগে কারণ জানুন।'}}];
function pestsPage(){return `<div class="wrap">${pageTop(t('Pest & disease library','পোকা ও রোগের পরিচিতি'),t('Compare visible symptoms, learn what to observe and choose an IPM-first response.','দৃশ্যমান লক্ষণ মিলিয়ে দেখুন, কী পর্যবেক্ষণ করবেন জানুন এবং আইপিএমভিত্তিক ব্যবস্থা নিন।'))}<div class="page-content"><div class="toolbar"><label class="sr-only" for="pest-search">${t('Search pests or crops','পোকা বা ফসল খুঁজুন')}</label><input id="pest-search" type="search" placeholder="${t('Search pest, crop or symptom…','পোকা, ফসল বা লক্ষণ খুঁজুন…')}" value="${esc(pestQuery)}"><div class="pill-group">${[['all',t('All','সব')],['pests',t('Insects','পোকা')],['diseases',t('Diseases & symptoms','রোগ ও লক্ষণ')]].map(([id,n])=>`<button class="pill" aria-pressed="${pestType===id}" data-action="pest-filter" data-id="${id}">${n}</button>`).join('')}</div></div><div id="pest-results"></div><div class="notice">${t('Photos and symptoms help observation; they do not confirm a diagnosis. For unclear or rapidly spreading damage, share photos and seek local advice.','ছবি ও লক্ষণ পর্যবেক্ষণে সহায়ক; এগুলো রোগনির্ণয় নিশ্চিত করে না। অস্পষ্ট বা দ্রুত ছড়ানো ক্ষতির ক্ষেত্রে ছবি দিয়ে স্থানীয় পরামর্শ নিন।')} ${link('help',t('Get help','সহায়তা নিন'))}</div></div></div>`;}
function renderPests(){let all=[...pestData.map((p,i)=>({...p,type:'pests',key:'p'+i})),...diseases.map((p,i)=>({...p,type:'diseases',key:'d'+i}))];let results=all.filter(p=>(pestType==='all'||p.type===pestType)&&JSON.stringify([p.en,p.bn]).toLowerCase().includes(pestQuery.toLowerCase()));$('#pest-results').innerHTML=results.length?`<div class="grid three">${results.map(p=>{let d=p[lang];return `<article class="card pest-card" id="${p.key}">${p.images?.length?`<img src="${p.images[0]}" alt="${esc(d.name)}" loading="lazy">`:`<div class="crop-art" style="height:110px">${I('leaf')}</div>`}<div class="card-pad"><span class="tag">${t(p.type==='pests'?'Insect':'Symptoms',p.type==='pests'?'পোকা':'লক্ষণ')}</span><h3>${d.name}</h3><p class="sci">${d.sci}</p><p><strong>${d.crop}</strong></p><details><summary>${t('Symptoms & management','লক্ষণ ও ব্যবস্থাপনা')}</summary><p>${d.damage}</p><p>${d.control}</p>${p.images?.[1]?`<img src="${p.images[1]}" alt="${esc(d.name)} · ${t('additional view','অতিরিক্ত ছবি')}" loading="lazy" style="margin-top:15px;border-radius:10px;height:150px">`:''}${link('help',t('Ask about these symptoms','এই লক্ষণ সম্পর্কে জিজ্ঞাসা করুন'))}</details></div></article>`}).join('')}</div>`:`<div class="empty">${t('No matches. Try another crop or symptom.','কিছু পাওয়া যায়নি। অন্য ফসল বা লক্ষণ লিখুন।')}</div>`;}
function ipmPage(){return `<div class="wrap">${pageTop(t('Integrated Pest Management','সমন্বিত বালাই ব্যবস্থাপনা'),t('Healthy crops, regular observation and a thoughtful response. IPM combines practical methods to reduce unnecessary pesticide use.','সুস্থ ফসল, নিয়মিত পর্যবেক্ষণ ও বিবেচিত ব্যবস্থা। অপ্রয়োজনীয় বালাইনাশক ব্যবহার কমাতে আইপিএম বিভিন্ন পদ্ধতির সমন্বয় করে।'))}<div class="page-content"><div class="steps">${IPM.map((s,i)=>`<article class="card step"><div class="step-number">${num(i+1).padStart(2,lang==='bn'?'০':'0')}</div><div><h3>${L(s.name)}</h3><p>${L(s.text)}</p></div></article>`).join('')}</div><div class="notice">${t('Keep a simple scouting record: date, crop stage, affected plants, pest and natural-enemy counts, and action taken. Check results before repeating treatment.','সহজ পর্যবেক্ষণ নোট রাখুন: তারিখ, ফসলের পর্যায়, আক্রান্ত গাছ, বালাই ও উপকারী পোকার সংখ্যা, এবং নেওয়া ব্যবস্থা। আবার প্রয়োগের আগে ফল দেখুন।')}</div><div class="flex-links">${link('pests',t('Open pest library','পোকার পরিচিতি দেখুন'),'btn secondary')}${sourceLink(4)}${link('help',t('Ask for guidance','পরামর্শ নিন'))}</div></div></div>`;}
function productsPage(){return `<div class="wrap">${pageTop(t('Products & growing inputs','পণ্য ও কৃষি উপকরণ'),t('Explore nine categories, understand what to check and prepare a product enquiry.','নয়টি পণ্যের ধরন দেখুন, কী যাচাই করবেন জানুন ও প্রয়োজনের বার্তা প্রস্তুত করুন।'))}<div class="page-content"><div class="notice"><strong>${t('Enquiry catalogue','পণ্য খোঁজার তালিকা')}</strong> · ${t('Stock, prices and delivery are confirmed directly before any order. No payment is collected here.','অর্ডারের আগে মজুত, দাম ও সরবরাহ সরাসরি নিশ্চিত করতে হবে। এখানে অর্থ নেওয়া হয় না।')}</div><div class="grid three">${productCards(Object.keys(productData))}</div></div></div>`;}
const PLANT_PHOTOS=[{file:'cactus.jpg',name:bi('Cactus','ক্যাকটাস'),author:'Paolo Neo',url:'https://commons.wikimedia.org/wiki/File:Cactus_in_flowerpot.jpg'},{file:'bamboo.jpg',name:bi('Lucky bamboo','লাকি ব্যাম্বু'),author:'Siddharth Patil',url:'https://commons.wikimedia.org/wiki/File:Dracaena_sanderiana.jpg'},{file:'snake.jpg',name:bi('Snake plant','স্নেক প্ল্যান্ট'),author:'Mokkie',url:'https://commons.wikimedia.org/wiki/File:Sansevieria_in_pot.jpg'}];
function gallery(){const p=PLANT_PHOTOS[indoorIndex];return `<section class="card card-pad"><h2>${t('Indoor plant gallery','ইনডোর গাছের গ্যালারি')}</h2><img id="indoor-photo" src="images/indoor-plants/${p.file}" alt="${L(p.name)}" style="width:100%;height:300px;object-fit:contain"><div style="display:flex;gap:18px;align-items:center;justify-content:center;margin-top:15px"><button class="icon-button" data-action="gallery-prev" aria-label="${t('Previous plant photo','আগের গাছের ছবি')}">←</button><span id="gallery-count" aria-live="polite">${num(indoorIndex+1)} / ${num(PLANT_PHOTOS.length)} · ${L(p.name)}</span><button class="icon-button" data-action="gallery-next" aria-label="${t('Next plant photo','পরের গাছের ছবি')}">→</button></div><p class="form-hint" style="margin-top:15px">${t('Reference photo, not current stock.','পরিচিতির ছবি; বর্তমান মজুতের ছবি নয়।')} <a href="${p.url}" target="_blank" rel="noopener noreferrer">${p.author} · Wikimedia Commons ↗</a> · ${t('Public domain / CC0','পাবলিক ডোমেইন / সিসি০')}</p></section>`;}
function categoryPage(id){if(!productData[id])return notFound();let d=productData[id][lang],ex=PRODUCT_EXTRA[id];return `<div class="wrap">${pageTop(clean(d.title),d.text,['products',t('Products','পণ্য')])}<div class="page-content detail-layout"><div class="stack"><section class="card card-pad"><div class="eyebrow">${t('Explore this category','এই ধরনের পণ্য জানুন')}</div><h2>${t('What you can ask about','যে বিষয়ে জানতে পারেন')}</h2><ul class="list">${L(ex.items).map(s=>`<li>${s}</li>`).join('')}</ul></section>${id==='indoor'?gallery():''}<section class="card card-pad"><h2>${t('Before you choose','নির্বাচনের আগে')}</h2><ul class="list">${L(ex.check).map(s=>`<li>${s}</li>`).join('')}</ul></section></div><aside class="stack"><section class="card card-pad"><span class="tag">${t('Availability on enquiry','যোগাযোগে প্রাপ্যতা জানুন')}</span><h3 style="margin-top:20px">${t('Tell us what you need','আপনার প্রয়োজন জানান')}</h3><p>${t('Include your crop, quantity, location and preferred time. Confirm the exact product, price and delivery directly.','ফসল, পরিমাণ, এলাকা ও সম্ভাব্য সময় জানান। নির্দিষ্ট পণ্য, দাম ও সরবরাহ সরাসরি নিশ্চিত করুন।')}</p><button class="btn full" style="margin-top:20px" data-action="product-help" data-id="${id}">${t('Prepare an enquiry','বার্তা প্রস্তুত করুন')}${I('arrow')}</button></section><div class="notice">${t('No stock or price is assumed. This catalogue supports informed enquiries.','মজুত বা দাম ধরে নেওয়া হয়নি। সচেতনভাবে খোঁজ নিতে এই তালিকা সহায়ক।')}</div>${id==='biopesticides'||id==='medicines'?link('ipm',t('Use an IPM-first approach','আইপিএমকে অগ্রাধিকার দিন')):sourceLink(1)}</aside></div></div>`;}
function aezPage(){return `<div class="wrap">${pageTop(t('Bangladesh AEZ explorer','বাংলাদেশের কৃষি-পরিবেশ অঞ্চল'),t('Thirty zones. One diverse landscape. Select a region on the map or use the searchable zone list.','ত্রিশটি অঞ্চল, বৈচিত্র্যময় বাংলাদেশ। মানচিত্রে অঞ্চল বাছুন অথবা তালিকায় খুঁজুন।'))}<div class="page-content"><div class="map-layout"><section class="card zone-list-panel"><label class="sr-only" for="zone-search">${t('Search all 30 zones','৩০টি অঞ্চল খুঁজুন')}</label><input id="zone-search" type="search" value="${esc(zoneQuery)}" placeholder="${t('Zone, number or district…','অঞ্চল, নম্বর বা জেলা…')}"><div id="zone-list" class="zone-list"></div></section><section class="card map-panel"><div class="map-north"><strong>↑</strong>${t('N','উত্তর')}</div><div class="map-tools">${[['zoom-in','plus',t('Zoom in','বড় করুন')],['zoom-out','minus',t('Zoom out','ছোট করুন')],['zoom-zone','target',t('Focus selected zone','নির্বাচিত অঞ্চল দেখুন')],['zoom-reset','reset',t('Reset map','সম্পূর্ণ মানচিত্র')]].map(([a,i,l])=>`<button class="icon-button" data-action="${a}" aria-label="${l}" title="${l}">${I(i)}</button>`).join('')}</div><div id="map-viewport" class="map-viewport"><div class="loading">${t('Loading zone boundaries…','অঞ্চলের সীমানা আসছে…')}</div></div><div class="map-caption">${t('Drag to pan · + / − to zoom · Select a zone. Generalised AEZ boundaries, not field boundaries.','টেনে সরান · + / − দিয়ে জুম · অঞ্চল বাছুন। সরলীকৃত এইজেড সীমানা; জমির সীমানা নয়।')}</div></section><aside class="card zone-detail" id="zone-detail" aria-live="polite"></aside></div><div class="notice"><strong>${t('Read the map with context.','মানচিত্র বুঝে ব্যবহার করুন।')}</strong> ${t('A district may cover multiple AEZs. Listed districts are examples, not district-wide classifications. Historical area figures follow BARC’s land-resource map, and may differ from later tables. Zone guidance below is general planning advice, not a field-specific recommendation.','এক জেলা একাধিক এইজেডে পড়তে পারে। উল্লেখিত জেলাগুলো উদাহরণ, পুরো জেলার শ্রেণিবিন্যাস নয়। ঐতিহাসিক আয়তন বিএআরসির ভূমি সম্পদ মানচিত্র অনুযায়ী; পরের সারণির সাথে পার্থক্য থাকতে পারে। নির্দেশনা সাধারণ পরিকল্পনার জন্য, নির্দিষ্ট জমির সুপারিশ নয়।')}</div><div class="flex-links">${sourceLink(0,t('Official BARC map','বিএআরসির মূল মানচিত্র'))}${sourceLink(2)}${link('sources',t('Map provenance & sources','মানচিত্র ও তথ্যের উৎস'))}</div></div></div>`;}
function renderZoneList(){let q=zoneQuery.toLowerCase().replace(/[০-৯]/g,c=>'০১২৩৪৫৬৭৮৯'.indexOf(c));let zs=zones.filter(z=>[z.id,z.name.en,z.name.bn,z.districts.en,z.districts.bn].join(' ').toLowerCase().includes(q));$('#zone-list').innerHTML=zs.length?zs.map(z=>`<button class="zone-button" data-action="zone" data-id="${z.id}" aria-pressed="${z.id===selectedZone}"><span class="zone-number">${num(z.id)}</span><span>${L(z.name)}</span></button>`).join(''):`<div class="empty">${t('No zone found. Try another name.','অঞ্চল পাওয়া যায়নি। অন্য নাম লিখুন।')}</div>`;}
function renderZone(){let z=zones[selectedZone-1];$('#zone-detail').innerHTML=`<span class="tag">${t('AEZ','এইজেড')} ${num(z.id)}</span><h2>${L(z.name)}</h2><div class="facts"><div class="fact"><small>${t('Historical mapped area','ঐতিহাসিক মানচিত্রে আয়তন')}</small><div class="zone-area">${num(z.area)} <span>${t('ha','হেক্টর')}</span></div></div><div class="fact"><small>${t('Landscape','ভূপ্রকৃতি')}</small><strong>${L(LANDSCAPES[z.type])}</strong></div><div class="fact"><small>${t('Example districts / location','জেলা / অবস্থানের উদাহরণ')}</small><strong>${L(z.districts)}</strong></div></div><details style="margin-top:18px;font-size:12px"><summary style="cursor:pointer;color:var(--green);font-weight:700">${t('Soil & land details','মাটি ও ভূমির তথ্য')}</summary><div style="margin-top:12px"><strong>${t('Soil texture','মাটির বুনট')}</strong><p>${L(z.soil)}</p><strong style="display:block;margin-top:12px">${t('Largest agricultural land class','প্রধান কৃষিভূমির শ্রেণি')}</strong><p>${L(LAND_CLASSES[z.land[0]])} · ${num(z.land[1])}%</p><p class="form-hint">${t('BARC FRG 2024, Table 3 and section 3.3. Conditions vary within each zone.','বিএআরসি সার সুপারিশমালা ২০২৪, সারণি ৩ ও অনুচ্ছেদ ৩.৩। অঞ্চলের ভেতরেও বৈচিত্র্য আছে।')}</p></div></details><div style="margin-top:20px"><div class="mini-label">${t('Planning consideration','পরিকল্পনায় বিবেচ্য')}</div><p style="margin-top:8px">${L(CONSIDERATIONS[z.type])}</p></div><button class="btn small full" data-action="zone-help">${t('Ask about this zone','এই অঞ্চল সম্পর্কে জিজ্ঞাসা')}${I('arrow')}</button><p style="font-size:9px;margin-top:13px">${t('Names & area: BARC LRI. District examples: FRG 2024, Table 3.','নাম ও আয়তন: বিএআরসি এলআরআই। জেলার উদাহরণ: সার সুপারিশমালা ২০২৪, সারণি ৩।')}</p>`;$$('.aez-path,.zone-marker').forEach(el=>{el.classList.toggle('selected',Number(el.dataset.zone)===selectedZone);if(el.matches('.aez-path'))el.setAttribute('aria-pressed',String(Number(el.dataset.zone)===selectedZone))});}
async function loadMap(){if(mapData)return mapData;if(!mapLoading)mapLoading=fetch('map-paths.json').then(r=>{if(!r.ok)throw Error('map');return r.json()}).then(j=>(mapData=j));return mapLoading;}
function mapSVG(mini=false){const colors=['#c5d4a3','#d9ddb7','#a6bf85','#d8c792','#b9cba8','#b5d3bc','#d6dca2','#c4bba0','#d8d0aa','#92b69c'];return `<svg xmlns="http://www.w3.org/2000/svg" ${mini?'class="mini-map"':'id="aez-map"'} viewBox="${mini?'0 0 500 710':viewBox.join(' ')}" ${mini?'aria-hidden="true"':`role="group" aria-label="${t('Interactive map of 30 Bangladesh agro-ecological zones','বাংলাদেশের ৩০ কৃষি-পরিবেশ অঞ্চলের মানচিত্র')}"`}><g>${mapData.paths.map(p=>`<path ${mini?'':`class="aez-path ${p.id===selectedZone?'selected':''}" data-zone="${p.id}" tabindex="0" role="button" aria-pressed="${p.id===selectedZone}" aria-label="${t('AEZ','এইজেড')} ${num(p.id)}: ${L(zones[p.id-1].name)}"`} d="${p.d}" fill="${colors[(p.id-1)%colors.length]}">${mini?'':`<title>${num(p.id)} · ${L(zones[p.id-1].name)}</title>`}</path>`).join('')}</g>${mini?'':`<g>${Object.entries(mapData.centers).map(([id,p])=>`<g class="zone-marker ${Number(id)===selectedZone?'selected':''}" data-zone="${id}" transform="translate(${p.join(' ')})" aria-hidden="true"><circle r="7"/><text>${num(id)}</text></g>`).join('')}</g>`}</svg>`;}
async function mountMap(){renderZoneList();renderZone();try{await loadMap();if(route()!=='aez')return;$('#map-viewport').innerHTML=mapSVG();attachMap();}catch{$('#map-viewport').innerHTML=`<div class="empty">${t('Map could not load. All 30 zones remain available in the list.','মানচিত্র আসেনি। তালিকা থেকে সব ৩০টি অঞ্চল দেখা যাবে।')}</div>`;}}
function chooseZone(id){if(id<1||id>30)return;selectedZone=id;sessionStorage.setItem('zee-zone',id);renderZoneList();renderZone();}
function setView(){const svg=$('#aez-map');if(svg)svg.setAttribute('viewBox',viewBox.join(' '));}
function zoom(f){let [x,y,w,h]=viewBox;let nw=Math.max(22,Math.min(650,w*f)),nh=nw*710/500;viewBox=[x+(w-nw)/2,y+(h-nh)/2,nw,nh];setView();}
function focusZone(){let p=$(`.aez-path[data-zone="${selectedZone}"]`);if(!p)return;let b=p.getBBox();let h=Math.max(40,b.height*1.3,b.width*1.3*710/500),w=h*500/710;viewBox=[b.x+b.width/2-w/2,b.y+b.height/2-h/2,w,h];setView();}
function attachMap(){let svg=$('#aez-map'),start=null,moved=false,pointers=new Map(),pinch=null;svg.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});svg.setPointerCapture(e.pointerId);moved=false;if(pointers.size===2){let a=[...pointers.values()];pinch={d:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y),v:[...viewBox]};start=null;return;}start={x:e.clientX,y:e.clientY,v:[...viewBox]};});svg.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2&&pinch){let a=[...pointers.values()],dist=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);viewBox=[...pinch.v];zoom(pinch.d/Math.max(1,dist));moved=true;return;}if(!start)return;let dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>5)moved=true;let scale=Math.min(svg.clientWidth/start.v[2],svg.clientHeight/start.v[3]);viewBox=[start.v[0]-dx/scale,start.v[1]-dy/scale,start.v[2],start.v[3]];setView();});const end=e=>{pointers.delete(e.pointerId);if(!moved){let el=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-zone]');if(el)chooseZone(Number(el.dataset.zone));}start=null;pinch=null;};svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',()=>{pointers.clear();start=null;pinch=null});svg.addEventListener('keydown',e=>{let id=e.target.dataset.zone;if(id&&(e.key==='Enter'||e.key===' ')){e.preventDefault();chooseZone(Number(id));}if(e.key==='+'||e.key==='='){e.preventDefault();zoom(.8)}if(e.key==='-'){e.preventDefault();zoom(1.25)}});}
const HELP_FIELDS=['name','crop','stage','location','zone','category','symptoms','duration','treatments'];
function field(name,label,placeholder='',type='text',required=false){return `<div class="field ${['symptoms','treatments'].includes(name)?'wide':''}"><label for="help-${name}">${label}${required?' *':''}</label>${type==='textarea'?`<textarea id="help-${name}" name="${name}" maxlength="4000" placeholder="${placeholder}" ${required?'required minlength="10"':''}>${esc(draft[name]||'')}</textarea>`:`<input class="input" id="help-${name}" name="${name}" type="${type}" maxlength="200" value="${esc(draft[name]||'')}" placeholder="${placeholder}" ${required?'required':''}>`}</div>`;}
function helpPage(){let first=helpStep===1,second=helpStep===2;return `<div class="wrap">${pageTop(t('A little help for your growing journey.','কৃষির পথে সহায়তায় পাশে আছি।'),t('Describe your crop or product need. Review your message, then choose how to contact Sayed Zishan Ahmed.','ফসলের সমস্যা বা পণ্যের প্রয়োজন জানান। বার্তা দেখে সায়েদ জিশান আহমেদের সাথে যোগাযোগের মাধ্যম বাছুন।'))}<div class="page-content detail-layout"><section class="card form-card"><div class="form-step-head">${[t('Your crop','আপনার ফসল'),t('The details','সমস্যার বিবরণ'),t('Review & contact','দেখুন ও যোগাযোগ করুন')].map((n,i)=>`<span class="${helpStep===i+1?'active':''}"><span class="dot">${num(i+1)}</span>${n}</span>`).join('')}</div>${first||second?`<form id="help-form"><div class="form-grid">${first?`${field('name',t('Your name (optional)','আপনার নাম (ঐচ্ছিক)'),t('How should we address you?','আপনাকে কী নামে সম্বোধন করব?'))}<div class="field"><label for="help-crop">${t('Crop / plant','ফসল / গাছ')} *</label><select id="help-crop" name="crop" required><option value="">${t('Select a crop','ফসল বাছুন')}</option>${Object.keys(cropData).map(id=>`<option value="${id}" ${draft.crop===id?'selected':''}>${titleOf(cropData,id)}</option>`).join('')}<option value="other" ${draft.crop==='other'?'selected':''}>${t('Other / product enquiry','অন্যান্য / পণ্যের খোঁজ')}</option></select></div>${field('location',t('District & upazila / area','জেলা ও উপজেলা / এলাকা'),t('e.g. Double Mooring, Chattogram','যেমন: ডবলমুরিং, চট্টগ্রাম'),'text',true)}${field('stage',t('Crop age / growth stage (optional)','ফসলের বয়স / পর্যায় (ঐচ্ছিক)'),t('e.g. 30-day seedlings','যেমন: ৩০ দিনের চারা'))}<div class="field wide"><label for="help-zone">${t('AEZ, if known (optional)','এইজেড, জানা থাকলে (ঐচ্ছিক)')}</label><select id="help-zone" name="zone"><option value="">${t('I’m not sure','নিশ্চিত নই')}</option>${zones.map(z=>`<option value="${z.id}" ${String(draft.zone)===String(z.id)?'selected':''}>${num(z.id)} · ${L(z.name)}</option>`).join('')}</select></div>`:`<div class="field wide"><label for="help-category">${t('What do you need help with?','কোন বিষয়ে সহায়তা দরকার?')}</label><select id="help-category" name="category">${[['crop',t('Crop health & growing','ফসলের স্বাস্থ্য ও চাষ')],['aez',t('Land / AEZ information','জমি / এইজেডের তথ্য')],...Object.keys(productData).map(id=>[id,titleOf(productData,id)])].map(([id,n])=>`<option value="${id}" ${draft.category===id?'selected':''}>${n}</option>`).join('')}</select></div>${field('symptoms',t('Symptoms / product requirements','লক্ষণ / পণ্যের প্রয়োজন'),t('What do you see? Which part is affected? How many plants? For products, include quantity and preferred time.','কী লক্ষণ দেখছেন? কোন অংশ আক্রান্ত? কতগুলো গাছ? পণ্যের ক্ষেত্রে পরিমাণ ও সম্ভাব্য সময় লিখুন।'),'textarea',true)}${field('duration',t('When did it start? (optional)','কখন শুরু হয়েছে? (ঐচ্ছিক)'),t('e.g. 3 days ago','যেমন: ৩ দিন আগে'))}${field('treatments',t('What have you already tried? (optional)','ইতিমধ্যে কী করেছেন? (ঐচ্ছিক)'),t('Product names, dates and observations','পণ্যের নাম, তারিখ ও পর্যবেক্ষণ'),'textarea')}<div class="field wide"><label for="help-photos">${t('Add up to 3 photos (optional)','সর্বোচ্চ ৩টি ছবি দিন (ঐচ্ছিক)')}</label><input id="help-photos" type="file" accept="image/*" multiple><p class="form-hint">${t('Whole plant, close-up and surrounding area. Up to 8 MB each. Photos stay in this tab and must be attached manually when sending.','পুরো গাছ, কাছের ছবি ও আশপাশের ছবি দিন। প্রতিটি সর্বোচ্চ ৮ এমবি। ছবি এই ট্যাবেই থাকে; পাঠানোর সময় নিজে যুক্ত করুন।')}</p><div id="photo-preview" class="photo-preview"></div></div>`}</div><p class="form-hint" style="margin-top:18px">${t('* Required. Text can be saved on this device. Photos are not saved with drafts.','* চিহ্নিত তথ্য প্রয়োজন। লেখা এই ডিভাইসে রাখা যায়। খসড়ার সাথে ছবি রাখা হয় না।')}</p><div class="form-actions">${first?`<button class="btn secondary" type="button" data-action="save-draft">${t('Save draft','খসড়া রাখুন')}</button>`:`<button class="btn secondary" type="button" data-action="help-back">${t('Back','পিছনে')}</button>`}<button class="btn" type="submit">${first?t('Continue','এগিয়ে যান'):t('Review message','বার্তা দেখুন')}${I('arrow')}</button></div>${second?`<button type="button" class="link" style="margin-top:18px;border:0;background:none;padding:0" data-action="save-draft">${t('Save text draft on this device','লেখার খসড়া এই ডিভাইসে রাখুন')}</button>`:''}</form>`:`<h2 style="font-size:23px;margin-bottom:18px">${t('Ready to review','বার্তা দেখে নিন')}</h2><pre class="review">${esc(helpMessage())}</pre>${photos.length?`<p class="form-hint">${num(photos.length)} ${t('photo(s) selected. Attach them yourself in your email or WhatsApp.','টি ছবি বাছা হয়েছে। ইমেইল বা হোয়াটসঅ্যাপে নিজে যুক্ত করুন।')}</p>`:''}<div class="flex-links"><a class="btn" href="${emailURL()}">${I('mail')}${t('Open email','ইমেইল খুলুন')}</a><a class="btn secondary" href="${whatsappURL()}" target="_blank" rel="noopener noreferrer">${I('help')}${t('Open WhatsApp','হোয়াটসঅ্যাপ খুলুন')}</a><button class="btn secondary" data-action="copy-message">${I('copy')}${t('Copy','কপি')}</button><button class="btn secondary" data-action="download-message">${I('download')}${t('Save text','লেখা নামান')}</button></div><div class="notice">${t('Your message has not been sent. The buttons open your own email or WhatsApp so you can review and send it. Attach selected photos manually.','আপনার বার্তা পাঠানো হয়নি। বাটন আপনার ইমেইল বা হোয়াটসঅ্যাপ খুলবে; সেখান থেকে দেখে পাঠাবেন। বাছা ছবিগুলো নিজে যুক্ত করুন।')}</div><button class="link" style="border:0;background:none;padding:0" data-action="help-back">← ${t('Edit details','বিবরণ বদলান')}</button>`}</section><aside class="stack"><div class="card card-pad"><div class="eyebrow">${t('Free guidance','বিনামূল্যে সহায়তা')}</div><h3>${t('A clear question helps us help you.','স্পষ্ট প্রশ্নে সহায়তা সহজ হয়।')}</h3><ul class="list"><li>${t('Describe where symptoms first appeared.','প্রথম কোথায় লক্ষণ দেখা গেছে লিখুন।')}</li><li>${t('Include recent rain, watering and input use.','সাম্প্রতিক বৃষ্টি, সেচ ও ব্যবহৃত উপকরণ জানান।')}</li><li>${t('Keep original product labels and crop photos.','পণ্যের মূল লেবেল ও ফসলের ছবি রাখুন।')}</li></ul></div><div class="card"><a class="contact-row" href="tel:+8801305981300">${I('phone')}<span><strong>${t('Call Sayed Zishan','জিশানকে কল করুন')}</strong><small>+880 1305-981300</small></span></a><a class="contact-row" href="tel:16123">${I('phone')}<span><strong>${t('Agriculture Call Centre','কৃষি কল সেন্টার')}</strong><small>${t('AIS official advice · 16123','এআইএসের সরকারি পরামর্শ · ১৬১২৩')}</small></span></a></div><div class="card card-pad"><h3>${t('Your draft, your device','আপনার খসড়া, আপনার ডিভাইসে')}</h3><p>${t('This form prepares a message. It does not upload your details or photos. Saved text stays in this browser.','এই ফর্ম বার্তা প্রস্তুত করে। তথ্য বা ছবি আপলোড করে না। রাখা খসড়া এই ব্রাউজারেই থাকে।')}</p><div class="flex-links"><button class="link" style="border:0;background:none;padding:0" data-action="clear-draft">${t('Clear draft & photos','খসড়া ও ছবি মুছুন')}</button></div></div></aside></div></div>`;}
function collectDraft(){const f=$('#help-form');if(!f)return;for(const [k,v] of new FormData(f))if(HELP_FIELDS.includes(k))draft[k]=String(v).trim();}
function helpMessage(){let lines=[t('Agriculture help / product enquiry — Agri Solution BD','কৃষি সহায়তা / পণ্যের খোঁজ — Agri Solution BD')];const vals=[['name',t('Name','নাম')],['crop',t('Crop','ফসল')],['stage',t('Stage','পর্যায়')],['location',t('Location','অবস্থান')],['zone',t('AEZ','এইজেড')],['category',t('Topic','বিষয়')],['duration',t('Since','শুরুর সময়')],['symptoms',t('Details','বিবরণ')],['treatments',t('Already tried','ইতিমধ্যে করা ব্যবস্থা')]];for(let [key,label] of vals){let v=draft[key];if(!v)continue;if(key==='crop')v=cropData[v]?titleOf(cropData,v):t('Other / product enquiry','অন্যান্য / পণ্যের খোঁজ');if(key==='zone')v=zones[Number(v)-1]?`${num(Number(v))} · ${L(zones[Number(v)-1].name)}`:v;if(key==='category')v=productData[v]?titleOf(productData,v):v==='aez'?t('Land / AEZ','জমি / এইজেড'):t('Crop health & growing','ফসলের স্বাস্থ্য ও চাষ');lines.push(`${label}: ${v}`);}return lines.join('\n\n');}
function emailURL(){return 'mailto:szishanahmed0@gmail.com?subject='+encodeURIComponent(t('Agriculture enquiry','কৃষি সংক্রান্ত প্রশ্ন')+' · Agri Solution BD')+'&body='+encodeURIComponent(helpMessage());}
function whatsappURL(){return 'https://wa.me/8801305981300?text='+encodeURIComponent(helpMessage());}
function showPhotos(){const el=$('#photo-preview');if(!el)return;el.innerHTML=photos.map((p,i)=>`<figure><img src="${p.url}" alt="${t('Selected crop photo','বাছা ফসলের ছবি')} ${num(i+1)}"><button type="button" data-action="remove-photo" data-id="${i}" aria-label="${t('Remove photo','ছবি সরান')} ${num(i+1)}">×</button></figure>`).join('');}
function aboutPage(){return `<div class="wrap">${pageTop(t('About Me','আমার সম্পর্কে'),t('Agriculture knowledge, useful products and a commitment to helping people.','কৃষিজ্ঞান, প্রয়োজনীয় পণ্য ও মানুষের পাশে থাকার প্রতিশ্রুতি।'))}<div class="page-content stack"><div class="card about-profile"><img src="images/my-photo.jpg" alt="Sayed Zishan Ahmed"><div><div class="eyebrow">${t('The person behind Zee Agri','জি এগ্রির পেছনের মানুষ')}</div><h2>${t('Sayed Zishan Ahmed','সায়েদ জিশান আহমেদ')}</h2><p>${t('Diploma in Agriculture · Agriculture Training Institute, Hathazari, Chattogram','ডিপ্লোমা ইন এগ্রিকালচার · কৃষি প্রশিক্ষণ ইনস্টিটিউট, হাটহাজারী, চট্টগ্রাম')}</p></div></div><div class="grid two"><div class="card card-pad"><h3>${t('Why Agri Solution BD?','কেন এগ্রি সলিউশন বিডি?')}</h3><p>${t('A practical agriculture platform for farmers, growers, students and plant enthusiasts. The goal is to make useful knowledge easier to find, connect people with the right inputs, and offer free guidance wherever possible.','কৃষক, চাষি, শিক্ষার্থী ও গাছপ্রেমীদের জন্য বাস্তবমুখী কৃষি প্ল্যাটফর্ম। প্রয়োজনীয় জ্ঞান সহজে পৌঁছানো, সঠিক উপকরণের সাথে সংযোগ এবং সম্ভব হলে বিনামূল্যে সহায়তাই লক্ষ্য।')}</p></div><div class="card card-pad"><h3>${t('What I care about','আমার আগ্রহ')}</h3><p>${t('Crop production, pest and disease identification, integrated pest management, healthy soil, rooftop gardens and modern agricultural technology. I value local context and source-based information.','ফসল উৎপাদন, পোকা ও রোগ শনাক্তকরণ, সমন্বিত বালাই ব্যবস্থাপনা, সুস্থ মাটি, ছাদবাগান ও আধুনিক কৃষি প্রযুক্তি। স্থানীয় অবস্থা ও তথ্যসূত্রভিত্তিক জ্ঞানকে গুরুত্ব দিই।')}</p></div></div><div class="flex-links">${link('contact',t('Get in touch','যোগাযোগ করুন'),'btn')}${link('sources',t('Our information sources','তথ্যের উৎস'),'btn secondary')}</div></div></div>`;}
function contactPage(){return `<div class="wrap">${pageTop(t('Let’s talk agriculture.','কৃষি নিয়ে কথা হোক।'),t('For growing questions, product enquiries or ideas for the platform, choose a way to get in touch.','চাষের প্রশ্ন, পণ্যের খোঁজ বা প্ল্যাটফর্মের পরামর্শ দিতে যোগাযোগ করুন।'))}<div class="page-content detail-layout"><div class="card"><a class="contact-row" href="mailto:szishanahmed0@gmail.com">${I('mail')}<span><strong>${t('Email','ইমেইল')}</strong><small>szishanahmed0@gmail.com</small></span>${I('arrow')}</a><a class="contact-row" href="tel:+8801305981300">${I('phone')}<span><strong>${t('Phone','ফোন')}</strong><small>+880 1305-981300</small></span>${I('arrow')}</a><a class="contact-row" href="https://www.facebook.com/s.zishan.ahmed" target="_blank" rel="noopener noreferrer">${I('external')}<span><strong>${t('Facebook profile','ফেসবুক প্রোফাইল')}</strong><small>${t('Sayed Zishan Ahmed','সায়েদ জিশান আহমেদ')}</small></span>${I('arrow')}</a><div class="contact-row">${I('pin')}<span><strong>${t('Based in','অবস্থান')}</strong><small>${t('Chattogram, Bangladesh','চট্টগ্রাম, বাংলাদেশ')}</small></span></div></div><div class="card card-pad"><div class="eyebrow">${t('Make your question clear','প্রশ্নটি গুছিয়ে নিন')}</div><h2 style="font-size:25px">${t('Need help with your crop?','ফসলে সহায়তা দরকার?')}</h2><p style="margin-top:16px">${t('Our farmer-help flow helps you prepare crop details and observations before contacting us.','যোগাযোগের আগে কৃষক সহায়তা ফর্মে ফসলের বিবরণ ও পর্যবেক্ষণ গুছিয়ে নিতে পারবেন।')}</p>${link('help',t('Prepare a question','প্রশ্ন প্রস্তুত করুন'),'btn')}</div></div></div>`;}
function sourcesPage(){return `<div class="wrap">${pageTop(t('Sources & information','তথ্যসূত্র ও তথ্যের ব্যবহার'),t('Know where the information comes from and how to use it. Sources checked on 8 November 2026.','তথ্যের উৎস জানুন ও বুঝে ব্যবহার করুন। তথ্যসূত্র যাচাই: ৮ নভেম্বর ২০২৬।'))}<div class="page-content"><div class="source-list">${SOURCES.map(s=>`<article class="card source-card">${I('book')}<div><h3><a href="${lang==='bn'&&s.bnurl?s.bnurl:s.url}" target="_blank" rel="noopener noreferrer">${L(s.title)} ↗</a></h3><p>${L(s.desc)}</p></div></article>`).join('')}</div><div class="notice">${t('Zone names and historical areas follow BARC’s Land Resources Information and Maps. Selected district examples follow FRG 2024 Table 3; historical and newer area tables differ slightly. Landscapes are grouped for navigation. Planning tips and crop/product checklists are general editorial guidance. Bangla text is a translation for this site, not an official source translation.','অঞ্চলের নাম ও ঐতিহাসিক আয়তন বিএআরসির ভূমি সম্পদ তথ্য ও মানচিত্র অনুযায়ী। জেলার নির্বাচিত উদাহরণ সার সুপারিশমালা ২০২৪-এর সারণি ৩ অনুযায়ী; পুরোনো ও নতুন আয়তনের সারণিতে সামান্য পার্থক্য আছে। সহজে খুঁজতে ভূপ্রকৃতি দলভুক্ত। পরিকল্পনার পরামর্শ ও ফসল-পণ্যের যাচাইতালিকা সাধারণ সম্পাদকীয় নির্দেশনা। বাংলা লেখা এই সাইটের অনুবাদ, উৎসের সরকারি অনুবাদ নয়।')}</div><div class="card card-pad"><h3>${t('Images & local privacy','ছবি ও ডিভাইসে তথ্য')}</h3><p style="margin-top:12px">${t('Profile and insect images were retained from the supplied zee-agri website. Indoor reference photos are public-domain / CC0 Wikimedia Commons images, credited in the gallery. Landscape photograph: Unsplash (photo-1500382017468-9049fed747ef); decorative, not a location claim. Language, theme, date position and saved help text stay in your browser. Photos selected in farmer help remain in memory in this tab. The form has no automatic submission.','প্রোফাইল ও পোকার ছবি সরবরাহকৃত জি-এগ্রি সাইট থেকে রাখা হয়েছে। ইনডোর গাছের পরিচিতির ছবি উইকিমিডিয়ার পাবলিক ডোমেইন / সিসি০ ছবি; গ্যালারিতে নাম দেওয়া আছে। ভূদৃশ্যের ছবি: আনস্প্ল্যাশ (photo-1500382017468-9049fed747ef); সাজসজ্জার জন্য, নির্দিষ্ট এলাকার দাবি নয়। ভাষা, থিম, তারিখের অবস্থান ও রাখা খসড়া আপনার ব্রাউজারে থাকে। সহায়তা ফর্মে বাছা ছবি শুধু এই ট্যাবের মেমরিতে থাকে। ফর্ম থেকে স্বয়ংক্রিয়ভাবে কিছু পাঠানো হয় না।')}</p></div></div></div>`;}
function notFound(){return `<div class="wrap"><div class="page-top"><h1>${t('This page isn’t here.','পাতাটি পাওয়া যায়নি।')}</h1><p>${t('Explore the crop guides or return home.','ফসলের তথ্য দেখুন অথবা হোমে ফিরুন।')}</p><div class="flex-links">${link('home',t('Go home','হোমে যান'),'btn')}</div></div></div>`;}
function render(){document.documentElement.lang=lang;document.documentElement.dataset.theme=theme;document.body.classList.toggle('large',font==='large'||font==='extra');let r=route(),[page,id]=r.split('/');let views={home,crops:cropsPage,crop:()=>cropPage(id),pests:pestsPage,ipm:ipmPage,products:productsPage,category:()=>categoryPage(id),aez:aezPage,help:helpPage,about:aboutPage,contact:contactPage,sources:sourcesPage};$('#main').innerHTML=(views[page]||notFound)();document.title=`${page==='home'?'Agri Solution BD':$('#main h1')?.textContent||t('Agriculture','কৃষি')} · Zee Agri`;header();footer();renderDate();if(page==='pests')renderPests();if(page==='aez')mountMap();if(page==='help')showPhotos();if(page==='home')loadMap().then(()=>{if($('#home-map'))$('#home-map').innerHTML=mapSVG(true)}).catch(()=>{});}
function setLanguage(v){collectDraft();lang=v;save('zeeAgriLanguage',v);let s=$('#search-dialog').open,settings=$('#settings-dialog').open,query=$('#global-search')?.value||'';render();if(s){searchContent(query);$('#global-search').focus()}if(settings)settingsContent();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function settingsContent(){$('#settings-dialog').innerHTML=`<div class="dialog-head"><h2>${t('Make it yours','আপনার মতো সাজান')}</h2><button class="icon-button" data-action="close-settings" aria-label="${t('Close settings','সেটিংস বন্ধ করুন')}">${I('close')}</button></div><div class="dialog-body"><div class="settings-row"><div><strong>${t('Language','ভাষা')}</strong><small>${t('All pages and information','সব পাতা ও তথ্য')}</small></div><select id="settings-language" aria-label="${t('Language','ভাষা')}"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="bn" ${lang==='bn'?'selected':''}>বাংলা</option></select></div><div class="settings-row"><div><strong>${t('Appearance','থিম')}</strong><small>${t('Comfort for day and night','দিন ও রাতের জন্য')}</small></div><select id="theme-select" aria-label="${t('Theme','থিম')}"><option value="light" ${theme==='light'?'selected':''}>${t('Light','হালকা')}</option><option value="dark" ${theme==='dark'?'selected':''}>${t('Dark','গাঢ়')}</option></select></div><div class="settings-row"><div><strong>${t('Reading size','লেখার আকার')}</strong><small>${t('Choose comfortable text','স্বাচ্ছন্দ্যে পড়ুন')}</small></div><select id="font-size-select" aria-label="${t('Text size','লেখার আকার')}"><option value="normal" ${font==='normal'?'selected':''}>${t('Normal','স্বাভাবিক')}</option><option value="large" ${font!=='normal'?'selected':''}>${t('Large','বড়')}</option></select></div><button class="btn secondary full" data-action="reset-date">${t('Reset date widget position','তারিখের অবস্থান ফিরিয়ে আনুন')}</button><p class="form-hint" style="margin-top:15px">${t('Preferences are saved in this browser. Use the date handle to move the bilingual date widget.','পছন্দ এই ব্রাউজারে থাকে। তারিখের হ্যান্ডেল ধরে দুই ভাষার তারিখ সরাতে পারবেন।')}</p></div>`;}
function openSettings(){settingsContent();$('#settings-dialog').showModal();}
function searchContent(q=''){$('#search-dialog').innerHTML=`<div class="dialog-head"><h2>${t('Find something useful','প্রয়োজনীয় তথ্য খুঁজুন')}</h2><button class="icon-button" data-action="close-search" aria-label="${t('Close search','অনুসন্ধান বন্ধ করুন')}">${I('close')}</button></div><div class="dialog-body"><label class="sr-only" for="global-search">${t('Search crops, pests, products or AEZs','ফসল, পোকা, পণ্য বা এইজেড খুঁজুন')}</label><input id="global-search" type="search" value="${esc(q)}" placeholder="${t('Try rice, whitefly, seeds or Chattogram…','ধান, সাদা মাছি, বীজ বা চট্টগ্রাম লিখুন…')}" autocomplete="off"><div id="search-results" class="search-results"></div></div>`;searchResults(q);}
function searchResults(q){let all=[...navItems.map(([id,n])=>({title:n,href:id,type:bi('Page','পাতা'),keywords:n.en+' '+n.bn})),...Object.keys(cropData).map(id=>({title:bi(clean(cropData[id].en.title),clean(cropData[id].bn.title)),href:'crop/'+id,type:bi('Crop','ফসল'),keywords:JSON.stringify(cropData[id])})),...Object.keys(productData).map(id=>({title:bi(clean(productData[id].en.title),clean(productData[id].bn.title)),href:'category/'+id,type:bi('Product category','পণ্যের ধরন'),keywords:JSON.stringify(productData[id])})),...pestData.map((p,i)=>({title:bi(p.en.name,p.bn.name),href:'pests',type:bi('Pest','পোকা'),pest:p[lang].name,keywords:JSON.stringify(p)})),...diseases.map(p=>({title:bi(p.en.name,p.bn.name),href:'pests',type:bi('Disease / symptom','রোগ / লক্ষণ'),pest:p[lang].name,keywords:JSON.stringify(p)})),...zones.map(z=>({title:bi(`AEZ ${z.id} · ${z.name.en}`,`এইজেড ${num(z.id)} · ${z.name.bn}`),href:'aez',type:bi('Agro zone','কৃষি অঞ্চল'),zone:z.id,keywords:JSON.stringify(z)})),...['about','contact','sources'].map(id=>({title:bi({about:'About Me',contact:'Contact',sources:'Sources'}[id],{about:'আমার সম্পর্কে',contact:'যোগাযোগ',sources:'তথ্যসূত্র'}[id]),href:id,type:bi('Page','পাতা'),keywords:id}))];q=q.toLowerCase().trim();let res=q?all.filter(a=>a.keywords.toLowerCase().includes(q)):all.slice(0,7);$('#search-results').innerHTML=`<div class="mini-label" style="padding:8px 10px">${q?`${num(res.length)} ${t('results','টি ফলাফল')}`:t('Explore the platform','সাইট ঘুরে দেখুন')}</div>`+(res.length?res.slice(0,50).map(a=>`<a class="search-result" href="#${a.href}" data-action="search-result" ${a.zone?`data-zone="${a.zone}"`:''} ${a.pest?`data-pest="${esc(a.pest)}"`:''}><strong>${L(a.title)}</strong><small>${L(a.type)}</small></a>`).join(''):`<div class="empty">${t('No results. Try a shorter term in Bangla or English.','ফলাফল নেই। বাংলা বা ইংরেজিতে ছোট শব্দ লিখুন।')}</div>`);}
function openSearch(){searchContent();$('#search-dialog').showModal();$('#global-search').focus();}
function bengaliDate(y,m,d){let startYear=(m>4||m===4&&d>=14)?y:y-1;let delta=Math.floor((Date.UTC(y,m-1,d)-Date.UTC(startYear,3,14))/86400000),gy=startYear+1;let leap=gy%4===0&&(gy%100!==0||gy%400===0);const lengths=[31,31,31,31,31,31,30,30,30,30,leap?30:29,30];let month=0;while(delta>=lengths[month]){delta-=lengths[month];month++;}return{day:delta+1,month,year:startYear-593};}
function dhakaDateParts(now=new Date()){return Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka',year:'numeric',month:'numeric',day:'numeric'}).formatToParts(now).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));}
function updateDate(){if(!$('.date-en'))return;let now=new Date(),p=dhakaDateParts(now),b=bengaliDate(p.year,p.month,p.day),months=['বৈশাখ','জ্যৈষ্ঠ','আষাঢ়','শ্রাবণ','ভাদ্র','আশ্বিন','কার্তিক','অগ্রহায়ণ','পৌষ','মাঘ','ফাল্গুন','চৈত্র'];$('.date-en').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Dhaka',day:'numeric',month:'long',year:'numeric'}).format(now);$('.date-bn').textContent=new Intl.NumberFormat('bn-BD',{useGrouping:false}).format(b.day)+' '+months[b.month]+' '+new Intl.NumberFormat('bn-BD',{useGrouping:false}).format(b.year);$('.date-time').textContent=new Intl.DateTimeFormat(lang==='bn'?'bn-BD':'en-GB',{timeZone:'Asia/Dhaka',hour:'2-digit',minute:'2-digit'}).format(now)+' · '+t('Dhaka','ঢাকা');}
function renderDate(){const w=$('#date-widget');w.classList.toggle('collapsed',dateCollapsed);w.innerHTML=`<div class="date-handle" id="date-handle" role="group" aria-label="${t('Drag to move date widget','তারিখ সরাতে টানুন')}"><span tabindex="0" role="button" id="date-mover" aria-label="${t('Move date with arrow keys; Home to reset','তীরচিহ্নে তারিখ সরান; হোম দিয়ে আগের জায়গায়')}">⠿ ${t('Today in the field','আজকের তারিখ')}</span><button data-action="date-toggle" aria-label="${dateCollapsed?t('Expand dates','তারিখ খুলুন'):t('Collapse dates','তারিখ ছোট করুন')}" aria-expanded="${!dateCollapsed}">${dateCollapsed?'+':'−'}</button></div><div class="date-content"><div class="date-en"></div><div class="date-bn"></div><div class="date-time"></div></div>`;let pos=getStore('zee-date-position',null);if(pos)positionDate(pos.x,pos.y);updateDate();const h=$('#date-handle');let start=null;h.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;let r=w.getBoundingClientRect();start={x:e.clientX-r.left,y:e.clientY-r.top};h.setPointerCapture(e.pointerId)});h.addEventListener('pointermove',e=>{if(start)positionDate(e.clientX-start.x,e.clientY-start.y)});h.addEventListener('pointerup',()=>{if(start){let r=w.getBoundingClientRect();save('zee-date-position',{x:r.left,y:r.top});start=null}});h.addEventListener('pointercancel',()=>start=null);$('#date-mover').addEventListener('keydown',e=>{if(e.key==='Home'){e.preventDefault();resetDate();return;}const dirs={ArrowLeft:[-15,0],ArrowRight:[15,0],ArrowUp:[0,-15],ArrowDown:[0,15]};if(dirs[e.key]){e.preventDefault();let r=w.getBoundingClientRect(),d=dirs[e.key];positionDate(r.left+d[0],r.top+d[1]);r=w.getBoundingClientRect();save('zee-date-position',{x:r.left,y:r.top})}});}
function positionDate(x,y){let w=$('#date-widget');w.style.left=Math.max(8,Math.min(innerWidth-w.offsetWidth-8,x))+'px';w.style.top=Math.max(8,Math.min(innerHeight-w.offsetHeight-(innerWidth<700?64:8),y))+'px';w.style.right='auto';w.style.bottom='auto';}
function resetDate(){try{localStorage.removeItem('zee-date-position')}catch{}let w=$('#date-widget');w.style.left=w.style.top=w.style.bottom=w.style.right='';renderDate();}
async function copyMessage(){try{await navigator.clipboard.writeText(helpMessage());toast(t('Message copied. Ready to paste.','বার্তা কপি হয়েছে। পেস্ট করতে পারবেন।'))}catch{let text=document.createElement('textarea');text.value=helpMessage();document.body.append(text);text.select();let ok=document.execCommand('copy');text.remove();toast(ok?t('Message copied.','বার্তা কপি হয়েছে।'):t('Select and copy the review text above.','উপরের বার্তা নির্বাচন করে কপি করুন।'))}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action,id=a.dataset.id;switch(action){case'menu':menuOpen=!menuOpen;header();break;case'language':setLanguage(lang==='en'?'bn':'en');break;case'search':openSearch();break;case'close-search':$('#search-dialog').close();break;case'settings':openSettings();break;case'close-settings':$('#settings-dialog').close();break;case'search-result':$('#search-dialog').close();if(a.dataset.zone){selectedZone=Number(a.dataset.zone);sessionStorage.setItem('zee-zone',selectedZone);if(route()==='aez'){chooseZone(selectedZone);focusZone()}}if(a.dataset.pest){pestQuery=a.dataset.pest;pestType='all';if(route()==='pests')render()}break;case'pest-filter':pestType=id;render();break;case'zone':chooseZone(Number(id));break;case'zoom-in':zoom(.8);break;case'zoom-out':zoom(1.25);break;case'zoom-reset':viewBox=[...viewBase];setView();break;case'zoom-zone':focusZone();break;case'zone-help':draft.zone=String(selectedZone);draft.category='aez';draft.crop=draft.crop||'other';helpStep=1;location.hash='help';break;case'crop-help':draft.crop=id;draft.category='crop';helpStep=1;location.hash='help';break;case'product-help':draft.category=id;draft.crop='other';helpStep=1;location.hash='help';break;case'help-back':collectDraft();helpStep=Math.max(1,helpStep-1);render();break;case'save-draft':collectDraft();save('zeeAgriHelpDraft',draft);toast(t('Text draft saved on this device.','খসড়ার লেখা এই ডিভাইসে রাখা হয়েছে।'));break;case'clear-draft':draft={};photos.forEach(p=>URL.revokeObjectURL(p.url));photos=[];helpStep=1;try{localStorage.removeItem('zeeAgriHelpDraft')}catch{}render();toast(t('Draft and selected photos cleared.','খসড়া ও বাছা ছবি মোছা হয়েছে।'));break;case'remove-photo':URL.revokeObjectURL(photos[Number(id)].url);photos.splice(Number(id),1);showPhotos();break;case'copy-message':copyMessage();break;case'download-message':{let blob=new Blob([helpMessage()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),n=document.createElement('a');n.href=url;n.download='Agri-Solution-BD-enquiry.txt';n.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case'date-toggle':dateCollapsed=!dateCollapsed;save('zee-date-collapsed',dateCollapsed);renderDate();break;case'reset-date':resetDate();toast(t('Date widget position reset.','তারিখের অবস্থান ফেরানো হয়েছে।'));break;case'gallery-prev':case'gallery-next':indoorIndex=(indoorIndex+(action==='gallery-next'?1:PLANT_PHOTOS.length-1))%PLANT_PHOTOS.length;render();break;}});
document.addEventListener('input',e=>{if(e.target.id==='crop-search')filterCrops(e.target.value);if(e.target.id==='global-search')searchResults(e.target.value);if(e.target.id==='zone-search'){zoneQuery=e.target.value;renderZoneList()}if(e.target.id==='pest-search'){pestQuery=e.target.value;renderPests()}if(e.target.closest('#help-form'))collectDraft();});
document.addEventListener('change',e=>{if(e.target.id==='settings-language')setLanguage(e.target.value);if(e.target.id==='theme-select'){theme=e.target.value;save('zeeAgriTheme',theme);document.documentElement.dataset.theme=theme}if(e.target.id==='font-size-select'){font=e.target.value;save('zeeAgriFontSize',font);document.body.classList.toggle('large',font!=='normal')}if(e.target.id==='help-photos'){for(const f of e.target.files){if(photos.length>=3){toast(t('Choose up to three photos.','সর্বোচ্চ তিনটি ছবি বাছুন।'));break;}if(!f.type.startsWith('image/')||f.size>8*1024*1024){toast(t('Use an image smaller than 8 MB.','৮ এমবির ছোট ছবি দিন।'));continue;}photos.push({file:f,url:URL.createObjectURL(f)})}e.target.value='';showPhotos();}});
document.addEventListener('submit',e=>{if(e.target.id==='help-form'){e.preventDefault();if(!e.target.reportValidity())return;collectDraft();helpStep=Math.min(3,helpStep+1);render();$('#main').focus();}});
document.addEventListener('keydown',e=>{if((e.key==='/'&&!e.ctrlKey&&!e.metaKey||e.key==='k'&&(e.ctrlKey||e.metaKey))&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){e.preventDefault();if(!$('#search-dialog').open&&!$('#settings-dialog').open)openSearch();}});
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}if(e.target.closest('nav a')){menuOpen=false;header();}if(e.target.matches('dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('hashchange',()=>{collectDraft();menuOpen=false;render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
window.addEventListener('resize',()=>{const pos=getStore('zee-date-position',null);if(pos)positionDate(pos.x,pos.y)});
setInterval(updateDate,30000);
render();
